<?php require __DIR__.'/inc/header.php';$title='Menus Builder';$pdo=db();if(is_post()){verify_csrf();$a=(string)post('action');if($a==='menu'){$pdo->prepare('INSERT INTO menus(name,location) VALUES(?,?)')->execute([trim((string)post('name')),post('location','header')]);flash('success','Menu created.');}elseif($a==='item'){$pdo->prepare('INSERT INTO menu_items(menu_id,label,url,target,sort_order,visibility,icon) VALUES(?,?,?,?,?,?,?)')->execute([(int)post('menu_id'),trim((string)post('label')),trim((string)post('url')),post('target','_self'),(int)post('sort_order',0),post('visibility','all'),post('icon','')]);flash('success','Menu item added.');}elseif($a==='delete_item'){$pdo->prepare('DELETE FROM menu_items WHERE id=?')->execute([(int)post('id')]);flash('success','Menu item deleted.');}redirect('/admin/menus.php');}$menus=$pdo->query('SELECT * FROM menus ORDER BY id DESC')->fetchAll();$items=$pdo->query('SELECT * FROM menu_items ORDER BY menu_id,sort_order,id')->fetchAll();?><div class="grid xl:grid-cols-2 gap-6"><div class="space-y-6"><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg">Create Menu</div><form method="post" class="mt-4 grid sm:grid-cols-2 gap-3"><?=csrf_input()?><input type="hidden" name="action" value="menu"><input name="name" required placeholder="Menu name" class="rounded-xl border-slate-200"><select name="location" class="rounded-xl border-slate-200"><option>header</option><option>footer</option><option>offcanvas</option></select><button class="sm:col-span-2 grad600 text-white rounded-xl py-3 font-black">Create Menu</button></form></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg">Add Menu Item</div><form method="post" class="mt-4 grid sm:grid-cols-2 gap-3"><?=csrf_input()?><input type="hidden" name="action" value="item"><select name="menu_id" class="rounded-xl border-slate-200"><?php foreach($menus as $m): ?><option value="<?=$m['id']?>"><?=e($m['name'])?> · <?=e($m['location'])?></option><?php endforeach; ?></select><input name="label" required placeholder="Label" class="rounded-xl border-slate-200"><input name="url" required placeholder="/articles/hello-world" class="rounded-xl border-slate-200 sm:col-span-2"><input name="icon" placeholder="Iconify icon name" class="rounded-xl border-slate-200"><input type="number" name="sort_order" value="0" class="rounded-xl border-slate-200"><select name="target" class="rounded-xl border-slate-200"><option>_self</option><option>_blank</option></select><select name="visibility" class="rounded-xl border-slate-200"><option>all</option><option>logged_in</option><option>logged_out</option></select><button class="sm:col-span-2 grad600b text-white rounded-xl py-3 font-black">Add Item</button></form></div></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg">Current Navigation</div><div class="space-y-3 mt-4"><?php foreach($menus as $m): ?><div class="rounded-xl bg-slate-50 p-3"><div class="font-bold"><?=e($m['name'])?> <span class="text-xs text-slate-400">· <?=e($m['location'])?></span></div><?php foreach($items as $i): ?><?php if($i['menu_id']==$m['id']): ?><div class="mt-2 flex items-center gap-2 text-sm pl-3 border-l-2 border-slate-200"><span><?=e($i['label'])?></span><span class="text-slate-400 truncate flex-1"><?=e($i['url'])?></span><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="delete_item"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="text-rose-600 text-xs font-bold">x</button></form></div><?php endif; ?><?php endforeach; ?></div><?php endforeach; ?></div></div></div><?php require __DIR__.'/inc/footer.php'; ?>